div.script:
window.luwaOpenPortfolioPreview = function(el) {
    var card = el.closest('.luwa-browser-card');
    if (!card) return;
    var img = card.querySelector('.luwa-browser-page-img');
    var link = card.querySelector('.luwa-browser-url');
    var modal = document.getElementById('luwaPortfolioPreviewModal');
    if (!modal || !img || !link) return;
    document.getElementById('luwaPmodalImg').src = img.src;
    document.getElementById('luwaPmodalUrl').href = link.href;
    document.getElementById('luwaPmodalVisit').href = link.href;
    document.getElementById('luwaPmodalDomain').textContent = link.textContent.trim();
    modal.classList.add('is-open');
};
document.addEventListener('click', function(e) {
    var img = e.target.closest('.luwa-browser-page-img');
    if (img) {
        window.luwaOpenPortfolioPreview(img);
    }
});

xpath.script:
(function() {
    if (window.__luwaNewsletterBound) return;
    window.__luwaNewsletterBound = true;
    document.addEventListener('submit', function(e) {
        var form = e.target.closest('form.luwa-newsletter-ajax-form, form.subscribe-one__form, form.luwa-footer-form');
        if (!form) return;
        e.preventDefault();
        var emailInput = form.querySelector('input[type="email"], input[name="email"]');
        var btn = form.querySelector('button[type="submit"]');
        var feedback = form.parentElement.querySelector('.luwa-newsletter-feedback') || form.querySelector('.luwa-newsletter-feedback');
        if (!feedback) {
            feedback = document.createElement('div');
            feedback.className = 'luwa-newsletter-feedback mt-2';
            feedback.style.fontWeight = '700';
            feedback.style.fontSize = '14px';
            form.insertAdjacentElement('afterend', feedback);
        }
        var emailVal = emailInput ? emailInput.value.trim() : '';
        if (!emailVal) return;
        if (btn) btn.disabled = true;
        feedback.style.display = 'block';
        feedback.style.color = '#0284c7';
        feedback.textContent = 'Subscribing your email...';

        var body = new URLSearchParams();
        body.append('email', emailVal);
        body.append('ajax', '1');

        fetch('/luwatech/newsletter/subscribe', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8',
                'Accept': 'application/json',
                'X-Requested-With': 'XMLHttpRequest'
            },
            body: body.toString()
        })
        .then(function(r) { return r.json(); })
        .then(function(data) {
            if (data && data.ok) {
                feedback.style.color = '#10b981';
                feedback.innerHTML = '✓ ' + (data.message || 'Subscribed to our mailing list!');
                if (emailInput) emailInput.value = '';
            } else {
                feedback.style.color = '#ef4444';
                feedback.textContent = (data && data.message) || 'Could not subscribe. Please check your email.';
            }
        })
        .catch(function() {
            feedback.style.color = '#ef4444';
            feedback.textContent = 'Network error. Please try again.';
        })
        .finally(function() {
            if (btn) btn.disabled = false;
        });
    });
})();
